"""Brute-force solvers written from the problem definitions."""

from __future__ import annotations

from itertools import combinations
from typing import Any


def solve_vertex_cover(instance: dict[str, Any]) -> bool:
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    if k < 0:
        return False
    if k >= n:
        return True
    for size in range(0, k + 1):
        for chosen in combinations(range(n), size):
            cover = set(chosen)
            if all(u in cover or v in cover for u, v in edges):
                return True
    return False


def solve_set_cover(instance: dict[str, Any]) -> bool:
    u = instance["universe_size"]
    sets = instance["sets"]
    k = instance["k"]
    if k < 0:
        return False
    if u == 0:
        return True
    if k > len(sets):
        k = len(sets)
    for size in range(0, k + 1):
        for chosen in combinations(range(len(sets)), size):
            covered = set()
            for index in chosen:
                covered.update(sets[index])
            if len(covered) == u:
                return True
    return False
EOF
